function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // Draw tree of life
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.moveTo(W / 2, 0);
  ctx.lineTo(W / 2, H);
  ctx.stroke();

  // Draw finches
  ctx.fillStyle = 'black';
  for (let i = 0; i < 5; i++) {
    ctx.save();
    ctx.translate(W / 2 + Math.sin(t + i) * 100, H / 2 + Math.cos(t + i) * 50);
    ctx.beginPath();
    ctx.arc(0, 0, 10, 0, 2 * Math.PI);
    ctx.fill();
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(0, 10);
    ctx.lineTo(0, 20);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(0, 10);
    ctx.lineTo(-5, 15);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(0, 10);
    ctx.lineTo(5, 15);
    ctx.stroke();
    ctx.restore();
  }

  // Draw darwin
  ctx.save();
  ctx.translate(W / 2, H - 50);
  ctx.beginPath();
  ctx.arc(0, 0, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(0, 20);
  ctx.lineTo(0, 40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(0, 20);
  ctx.lineTo(-10, 30);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(0, 20);
  ctx.lineTo(10, 30);
  ctx.stroke();
  ctx.restore();

  ctx.restore();
}
